insert into public.software (name, slug, tagline, description_short, description_full, logo_url, category_id, starting_price, price_currency, billing_period, price_is_net, price_unit, free_trial, trial_days, free_version, free_demo, pricing_plans, pricing_note, features, top_features, integrations, pros, cons, ideal_for, brand_color, gobd_compliant, datev_interface, e_invoicing, elster_submission, hosting_location, dpa_available, iso27001, tse_certified, skr_support, german_support, vendor_country, compliance_checked_at, affiliate_url, vendor_website, affiliate_network, vendor_name, founded_year, vendor_hq, support_types, countries_available, languages, editorial_rating, editorial_ease, editorial_value, editorial_service, editorial_functionality, editorial_verdict, editorial_review, editorial_author, editorial_tested_at, status, featured) values
('Haufe X360', 'haufe-x360', 'Cloud-ERP für wachsende Unternehmen', 'Cloud-ERP von Haufe mit Finanzen, Warenwirtschaft, Projekten und CRM für wachsende Mittelständler.', '<p>Haufe X360 ist das Cloud-ERP der Haufe Group für Unternehmen, die über Einzellösungen hinausgewachsen sind. Finanzen, Warenwirtschaft, Projekte und CRM sind integriert.</p><p>Die Lösung ist für den deutschen Markt lokalisiert und bietet einen DATEV-Export.</p>', null, (select id from public.categories where slug = 'erp-warenwirtschaft'), 49, 'EUR', 'month', true, 'user', false, null, false, true, '[]'::jsonb, 'Mindestumsatz 449 € im Monat, Preis nach Konfiguration', '["Warenwirtschaft","Einkauf & Bestellwesen","Auftragsabwicklung","Finanzbuchhaltung","E-Rechnung (XRechnung/ZUGFeRD)","Mehrlager & Versand","CRM-Funktionen","Controlling & Berichte"]'::jsonb, '["Für Wachstum ausgelegt","Deutsche Lokalisierung","Projektabrechnung"]'::jsonb, '["DATEV","Lexware Office","Microsoft 365"]'::jsonb, '["Moderne Cloud-Architektur","Gute deutsche Lokalisierung"]'::jsonb, '["Noch kleineres Partnernetz","Mindestbetrag von 449 € im Monat"]'::jsonb, 'Wachsende KMU mit 20 bis 250 Mitarbeitenden.', null, 'ja', 'export', '["XRechnung","ZUGFeRD"]'::jsonb, null, 'EU', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.haufe-x360.de', 'keins', 'Haufe-Lexware GmbH & Co. KG', null, 'Freiburg im Breisgau', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4, 3.8, 3.7, 4.1, 4.5, 'Haufe X360 ist ein Cloud-ERP für den gehobenen Mittelstand mit sehr flexibler Konfiguration. Der Mindestumsatz von 449 € im Monat zeigt, dass es nicht für Kleinbetriebe gedacht ist.', '<h3>Einordnung</h3><p>Haufe X360 deckt Finanzen, Vertrieb, Einkauf, Lager und Projekte ab und wird nach gebuchten Funktionen und Nutzern abgerechnet. Die Plattform ist für Unternehmen gedacht, die aus einer Sammlung von Einzellösungen ein zentrales System machen wollen.</p><h3>Preise</h3><p>Der Einstieg für Dienstleister liegt bei 49 € je Nutzer im Monat, mit Vertrieb oder im Großhandel deutlich darüber. Der monatliche Mindestbetrag beträgt 449 €. Eine Testversion gibt es nicht, dafür eine kostenlose Beratung mit Produktdemo.</p><h3>Fazit</h3><p>Für Mittelständler mit 20 Nutzern und mehr, die eine konfigurierbare Cloud-Lösung aus deutscher Hand suchen, ist Haufe X360 eine ernsthafte Option.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('awork', 'awork', 'Projektplanung und Zeiterfassung für Agenturen und Teams', 'Projektmanagement aus Hamburg mit Aufgaben, Auslastungsplanung und Zeiterfassung, gehostet in Deutschland.', '<p>awork verbindet Aufgaben- und Projektplanung mit Auslastungsplanung und Zeiterfassung. Besonders Agenturen und Dienstleister nutzen die Software, um Kundenprojekte zu planen und Zeiten abzurechnen.</p><p>Das Hamburger Unternehmen hostet die Daten in Deutschland und stellt einen AV-Vertrag bereit.</p>', null, (select id from public.categories where slug = 'projektmanagement'), 8, 'EUR', 'month', true, 'user', true, null, false, false, '[{"name":"Basic","price":8,"period":"month","unit":"user","features":["jährlich 5 €"]},{"name":"Standard","price":16,"period":"month","unit":"user","features":["jährlich 12 €"],"highlighted":true},{"name":"Professional","price":29,"period":"month","unit":"user","features":["jährlich 22 €"]}]'::jsonb, null, '["Aufgaben & Kanban","Gantt-Diagramm","Ressourcen & Auslastung","Zeiterfassung","Budget & Controlling","Dokumente & Dateien","Gastzugänge","Vorlagen"]'::jsonb, '["Auslastungsplanung im Team","Zeiterfassung integriert","Serverstandort Deutschland"]'::jsonb, '["Slack","Microsoft Teams","Google Calendar","Outlook","DATEV","Personio"]'::jsonb, '["Sehr aufgeräumtes Design","Starke Auslastungsplanung"]'::jsonb, '["Kein Gantt-Detailgrad wie bei klassischen PM-Tools","Budget-Funktionen ausbaufähig"]'::jsonb, 'Agenturen und Dienstleistungsteams mit 5 bis 200 Personen.', null, null, null, '[]'::jsonb, null, 'Deutschland', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.awork.com/de', 'keins', 'awork GmbH', null, 'Hamburg', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.4, 4.6, 4.2, 4.3, 4.3, 'awork aus Hamburg verbindet Aufgaben, Auslastungsplanung und Zeiterfassung in einer sehr aufgeräumten Oberfläche. Für Agenturen und Dienstleistungsteams ist es eine der besten Lösungen aus Deutschland.', '<h3>Was awork auszeichnet</h3><p>Viele Projekttools zeigen, was zu tun ist. awork zeigt zusätzlich, wer dafür Zeit hat. Die Auslastungsplanung macht auf einen Blick sichtbar, wer in der nächsten Woche überbucht ist, und die Zeiterfassung fließt direkt in die Projektauswertung.</p><h3>Preise</h3><p>Basic kostet 8 €, Standard 16 € und Professional 29 € je Nutzer im Monat. Bei jährlicher Zahlung sinken die Preise auf 5 €, 12 € und 22 €. KI-Funktionen lassen sich als Zusatzpaket buchen. Getestet werden kann ohne Kreditkarte, mit allen Funktionen im Team.</p><h3>Fazit</h3><p>Für Teams zwischen fünf und zweihundert Personen, die nach Stunden arbeiten oder abrechnen, ist awork eine sehr gute Wahl. Die Daten liegen in Deutschland.</p>', 'Nadeem Abbas', '2026-09-22', 'published', true),
('factro', 'factro', 'Projektmanagement-Software aus dem Ruhrgebiet', 'Projektmanagement aus Bochum mit Projektstrukturplan, Gantt und Kanban, DSGVO-konform in Deutschland gehostet.', '<p>factro bildet Projekte klassisch und agil ab: Projektstrukturplan, Gantt-Diagramm und Kanban-Boards greifen ineinander. Die Software ist besonders in Mittelstand und öffentlichen Einrichtungen verbreitet.</p><p>Die Server stehen in Deutschland.</p>', null, (select id from public.categories where slug = 'projektmanagement'), 0, 'EUR', 'month', true, 'user', true, null, true, false, '[{"name":"Basic","price":0,"period":"month","unit":"user","features":["Kostenlos für bis zu 3 Nutzer"]},{"name":"Business","price":19.99,"period":"month","unit":"user","features":["ab 3 Nutzern"],"highlighted":true},{"name":"Professional","price":29.99,"period":"month","unit":"user","features":["ab 3 Nutzern"]}]'::jsonb, null, '["Aufgaben & Kanban","Gantt-Diagramm","Ressourcen & Auslastung","Zeiterfassung","Dokumente & Dateien","Kommunikation & Chat","Gastzugänge","Vorlagen"]'::jsonb, '["Projektstrukturplan","Klassisch und agil","Serverstandort Deutschland"]'::jsonb, '["Outlook","Microsoft Teams","Zapier"]'::jsonb, '["Gute Mischung aus klassisch und agil","Deutscher Support"]'::jsonb, '["Weniger Integrationen","Mobile App ausbaufähig"]'::jsonb, 'Mittelständler und Behörden mit klassischen Projekten.', null, null, null, '[]'::jsonb, null, 'Deutschland', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.factro.de', 'keins', 'factro GmbH', null, 'Bochum', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.2, 4.2, 4.3, 4.1, 4.2, 'factro ist ein Projektmanagement-Tool aus Bochum mit Projektstrukturplan, Gantt und Kanban, gehostet in Deutschland. Die kostenlose Version für drei Nutzer macht den Einstieg leicht.', '<h3>Worum es geht</h3><p>factro verbindet klassische und agile Methoden. Projekte werden über einen Projektstrukturplan aufgebaut, im Gantt-Diagramm terminiert und im Kanban-Board abgearbeitet. Das spricht besonders Organisationen an, die mit formalen Projektstrukturen arbeiten.</p><h3>Preise</h3><p>Basic ist kostenlos für bis zu drei Nutzer. Business kostet 19,99 € und Professional 29,99 € je Nutzer im Monat, jeweils ab drei Nutzern. Für Behörden und Kommunen gibt es einen eigenen Government-Tarif.</p><h3>Fazit</h3><p>Für mittelständische Unternehmen und öffentliche Einrichtungen, die Wert auf deutsches Hosting und strukturierte Projektplanung legen, ist factro eine überzeugende Lösung.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Stackfield', 'stackfield', 'Sichere Kollaboration mit Ende-zu-Ende-Verschlüsselung', 'Kollaborationsplattform aus München mit Aufgaben, Chat und Dokumenten, Ende-zu-Ende-verschlüsselt, Hosting in Deutschland.', '<p>Stackfield vereint Projektmanagement, Team-Chat, Dokumente und Kalender in einer Plattform. Das Alleinstellungsmerkmal ist die optionale Ende-zu-Ende-Verschlüsselung, die Stackfield für Branchen mit hohen Vertraulichkeitsanforderungen interessant macht.</p><p>Die Daten liegen in ISO-27001-zertifizierten Rechenzentren in Deutschland.</p>', null, (select id from public.categories where slug = 'projektmanagement'), 9, 'EUR', 'month', true, 'user', true, 14, false, false, '[{"name":"Starter","price":9,"period":"month","unit":"user","features":["bis 10 Nutzer"]},{"name":"Business","price":14,"period":"month","unit":"user","features":["unbegrenzte Nutzer"]},{"name":"Premium","price":18,"period":"month","unit":"user","features":["unbegrenzte Nutzer"],"highlighted":true},{"name":"Enterprise","price":28,"period":"month","unit":"user","features":["unbegrenzte Nutzer"]}]'::jsonb, null, '["Aufgaben & Kanban","Gantt-Diagramm","Zeiterfassung","Dokumente & Dateien","Kommunikation & Chat","Gastzugänge","Vorlagen"]'::jsonb, '["Ende-zu-Ende-Verschlüsselung","Chat und Aufgaben in einem","Hosting in Deutschland"]'::jsonb, '["Outlook","Google Calendar","Zapier"]'::jsonb, '["Höchste Datenschutzstandards","Ersetzt mehrere Tools"]'::jsonb, '["Weniger Tiefe bei Ressourcenplanung","Kleineres Ökosystem"]'::jsonb, 'Teams mit hohen Datenschutzanforderungen, z. B. Kanzleien und Gesundheitswesen.', null, null, null, '[]'::jsonb, null, 'Deutschland', true, true, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.stackfield.com/de', 'keins', 'Stackfield GmbH', null, 'München', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.3, 4.3, 4.1, 4.3, 4.4, 'Stackfield aus München kombiniert Aufgaben, Chat, Dokumente und Videokonferenzen mit Ende-zu-Ende-Verschlüsselung und Hosting in Deutschland. Für datenschutzsensible Teams ist das ein starkes Paket.', '<h3>Das Konzept</h3><p>Stackfield will mehrere Werkzeuge ersetzen: Projektboards, Team-Chat, Dateiablage und Videotelefonie. Inhalte lassen sich Ende-zu-Ende verschlüsseln, was für Kanzleien, Beratungen und den öffentlichen Sektor ein echter Unterschied ist.</p><h3>Preise</h3><p>Starter kostet 9 € je Nutzer im Monat und ist auf zehn Nutzer begrenzt. Business kostet 14 €, Premium 18 € und Enterprise 28 € je Nutzer, jeweils ohne Nutzerlimit. Ein KI-Paket kostet 3,90 € zusätzlich. Bei jährlicher Zahlung sparen Sie 17 Prozent. Die 14 Tage kostenlose Testphase umfasst alle Premium-Funktionen und endet automatisch.</p><h3>Fazit</h3><p>Wer Slack, Trello und Dropbox durch eine datenschutzfreundliche deutsche Lösung ersetzen will, sollte Stackfield ausprobieren.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('OpenProject', 'openproject', 'Open-Source-Projektmanagement für Cloud und eigene Server', 'Open-Source-Projektmanagement aus Berlin mit Gantt, Agile Boards und Zeiterfassung, kostenlose Community-Edition.', '<p>OpenProject ist eine Open-Source-Software für klassisches und agiles Projektmanagement. Sie bietet Gantt-Diagramme, Agile Boards, Zeit- und Kostenerfassung sowie Wikis.</p><p>Die Community-Edition ist kostenlos und kann im eigenen Rechenzentrum betrieben werden; die Cloud-Variante wird in der EU gehostet. Viele Behörden setzen OpenProject aus Gründen der digitalen Souveränität ein.</p>', null, (select id from public.categories where slug = 'projektmanagement'), 0, 'EUR', 'month', true, 'user', true, 14, true, false, '[{"name":"Community","price":0,"period":"month","unit":"user","features":["Open Source, selbst gehostet"]},{"name":"Basic","price":5.95,"period":"month","unit":"user","features":["Cloud oder On-Premise"]},{"name":"Professional","price":10.95,"period":"month","unit":"user","features":["Cloud oder On-Premise"],"highlighted":true},{"name":"Premium","price":15.95,"period":"month","unit":"user","features":["Cloud oder On-Premise"]}]'::jsonb, null, '["Aufgaben & Kanban","Gantt-Diagramm","Ressourcen & Auslastung","Zeiterfassung","Budget & Controlling","Dokumente & Dateien","Vorlagen","On-Premise-Option"]'::jsonb, '["Open Source","On-Premise möglich","Digitale Souveränität"]'::jsonb, '["Nextcloud","GitLab","GitHub","OneDrive"]'::jsonb, '["Volle Datenhoheit","Kostenlose Community-Edition"]'::jsonb, '["Oberfläche funktional statt schick","Eigenbetrieb erfordert IT-Know-how"]'::jsonb, 'Behörden, Industrie und Organisationen mit Souveränitätsanspruch.', null, null, null, '[]'::jsonb, null, 'EU', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.openproject.org/de/', 'keins', 'OpenProject GmbH', null, 'Berlin', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch","und weitere"]'::jsonb, 4.2, 3.9, 4.6, 4, 4.5, 'OpenProject ist die führende Open-Source-Lösung für Projektmanagement mit Gantt, agilen Boards und Zeiterfassung. Die kostenlose Community-Edition und faire Cloud-Preise machen es besonders attraktiv.', '<h3>Was OpenProject bietet</h3><p>Die Berliner Software deckt klassisches und agiles Projektmanagement ab, von Arbeitspaketen und Meilensteinen über Gantt-Diagramme bis zu Scrum-Boards und Zeiterfassung. Sie kann in der Cloud oder auf eigenen Servern betrieben werden.</p><h3>Preise</h3><p>Die Community-Edition ist kostenlos und selbst gehostet. Basic kostet 5,95 €, Professional 10,95 € und Premium 15,95 € je Nutzer im Monat, jeweils in der Cloud oder vor Ort. Corporate gibt es auf Anfrage. Alle Editionen lassen sich 14 Tage kostenlos testen.</p><h3>Fazit</h3><p>Für Organisationen mit hohem Anspruch an Datenhoheit, etwa Behörden, Forschung und Ingenieurbüros, ist OpenProject eine der besten Wahlen.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('InLoox', 'inloox', 'Projektmanagement mit Outlook-Integration', 'Projektmanagement aus München, das sich tief in Microsoft Outlook integriert, als Cloud oder on-premise.', '<p>InLoox ist bekannt für seine enge Verzahnung mit Microsoft Outlook: Projekte, Aufgaben und E-Mails lassen sich direkt aus dem Postfach steuern. Zusätzlich gibt es eine Web-App.</p><p>Die Software ist als Cloud-Lösung mit Hosting in Deutschland oder für den Eigenbetrieb erhältlich.</p>', null, (select id from public.categories where slug = 'projektmanagement'), null, 'EUR', 'month', true, 'user', true, 14, false, true, '[]'::jsonb, null, '["Aufgaben & Kanban","Gantt-Diagramm","Ressourcen & Auslastung","Zeiterfassung","Budget & Controlling","Dokumente & Dateien","Vorlagen","On-Premise-Option"]'::jsonb, '["Outlook-Integration","Cloud oder on-premise","Budgetplanung"]'::jsonb, '["Outlook","Microsoft Teams","SharePoint"]'::jsonb, '["Ideal für Outlook-lastige Teams","Klassische PM-Methoden gut abgebildet"]'::jsonb, '["Weniger modern als Cloud-Neulinge","Preis nur auf Anfrage"]'::jsonb, 'Mittelständler mit Microsoft-Umgebung.', null, null, null, '[]'::jsonb, null, 'Deutschland', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.inloox.de', 'keins', 'InLoox GmbH', null, 'München', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4, 4, 3.7, 4.1, 4.3, 'InLoox ist tief in Microsoft Outlook integriert und damit ideal für Unternehmen, deren Projektarbeit im Postfach stattfindet. Preise gibt es nur auf Anfrage.', '<h3>Das Besondere</h3><p>InLoox aus München bringt Projektmanagement direkt in Outlook. Aufgaben, Zeitpläne und Dokumente liegen dort, wo viele Mitarbeitende ohnehin den ganzen Tag arbeiten. Eine Webversion steht zusätzlich zur Verfügung.</p><h3>Editionen und Test</h3><p>Professional beginnt bei fünf Nutzern, Enterprise und Enterprise Plus bei zehn, die Self-Hosted-Variante bei 20 Nutzern. Alle Editionen lassen sich 14 Tage kostenlos testen. Preise nennt InLoox auf Anfrage.</p><h3>Fazit</h3><p>Für Microsoft-geprägte Mittelständler mit klassischen Projekten ist InLoox eine naheliegende Wahl.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('MeisterTask', 'meistertask', 'Aufgabenmanagement mit Kanban-Boards', 'Intuitives Kanban-Aufgabenmanagement aus München mit kostenloser Basisversion.', '<p>MeisterTask organisiert Aufgaben in Kanban-Boards und automatisiert wiederkehrende Abläufe. Die Software ist schnell erlernt und eignet sich für Teams, die Aufgaben visuell steuern wollen.</p><p>Die Daten werden in der EU gehostet; eine kostenlose Basisversion steht zur Verfügung.</p>', null, (select id from public.categories where slug = 'projektmanagement'), 0, 'EUR', 'month', true, 'user', true, null, true, false, '[{"name":"Basic","price":0,"period":"month","unit":"user","features":["Bis zu 3 Projekte"]},{"name":"Pro","price":7,"period":"month","unit":"user","features":["Unbegrenzte Projekte"],"highlighted":true},{"name":"Business","price":12.5,"period":"month","unit":"user","features":["Zeitleiste, Rollen, Berichte"]}]'::jsonb, null, '["Aufgaben & Kanban","Zeiterfassung","Dokumente & Dateien","Gastzugänge","Vorlagen"]'::jsonb, '["Sehr intuitive Boards","Automatisierungen","Kostenlose Version"]'::jsonb, '["Slack","Microsoft Teams","Google Drive","MindMeister","Zapier"]'::jsonb, '["Schöne, einfache Oberfläche","Günstig"]'::jsonb, '["Kein echtes Gantt","Für komplexe Projekte zu schlank"]'::jsonb, 'Kleine Teams und Abteilungen.', null, null, null, '[]'::jsonb, null, 'EU', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.meistertask.com/de', 'keins', 'MeisterLabs GmbH', null, 'München', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch","und weitere"]'::jsonb, 4.2, 4.6, 4.3, 3.9, 3.8, 'MeisterTask ist ein intuitives Kanban-Tool aus München mit einer dauerhaft kostenlosen Version. Für kleine Teams und einfache Projekte ist es eine der angenehmsten Lösungen.', '<h3>Worum es geht</h3><p>MeisterTask organisiert Aufgaben auf Boards, mit Automatisierungen für wiederkehrende Abläufe und Integrationen in gängige Werkzeuge. Die Oberfläche ist so einfach, dass Teams ohne Schulung loslegen.</p><h3>Preise</h3><p>Basic ist dauerhaft kostenlos mit bis zu drei Projekten. Pro kostet 7 € und Business 12,50 € je Nutzer im Monat, Enterprise gibt es auf Anfrage. Bei jährlicher Zahlung sparen Sie bis zu 22 Prozent.</p><h3>Fazit</h3><p>Für komplexe Projektplanung mit Ressourcen und Budgets ist MeisterTask zu schlank. Für Teams, die ihre Aufgaben übersichtlich halten wollen, ist es ideal.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('monday.com', 'monday-com', 'Work OS für Teams jeder Größe', 'Flexible Work-Management-Plattform mit Boards, Automatisierungen und Dashboards, EU-Datenhaltung möglich.', '<p>monday.com ist eine flexible Plattform für Projekt- und Arbeitsmanagement. Boards lassen sich an nahezu jeden Prozess anpassen; Automatisierungen und Dashboards sorgen für Überblick.</p><p>Für europäische Kunden ist eine Datenhaltung in der EU verfügbar.</p>', null, (select id from public.categories where slug = 'projektmanagement'), 0, 'EUR', 'month', true, 'user', true, null, true, false, '[{"name":"Free","price":0,"period":"month","unit":"user","features":["Bis zu 2 Nutzer"]},{"name":"Basic","price":9,"period":"month","unit":"user","features":["Grundlegende Boards"]},{"name":"Standard","price":12,"period":"month","unit":"user","features":["Zeitleiste, Automatisierungen"],"highlighted":true},{"name":"Pro","price":19,"period":"month","unit":"user","features":["Zeiterfassung, erweiterte Automatisierung"]}]'::jsonb, 'bei jährlicher Zahlung', '["Aufgaben & Kanban","Gantt-Diagramm","Ressourcen & Auslastung","Zeiterfassung","Budget & Controlling","Dokumente & Dateien","Gastzugänge","Vorlagen"]'::jsonb, '["Sehr flexibel","Starke Automatisierungen","Hunderte Vorlagen"]'::jsonb, '["Slack","Microsoft Teams","Outlook","Gmail","Zoom","Salesforce","HubSpot"]'::jsonb, '["Extrem anpassbar","Moderne Oberfläche"]'::jsonb, '["Kosten steigen mit Nutzerzahl und Features","Mindestanzahl an Plätzen"]'::jsonb, 'Teams, die individuelle Workflows abbilden möchten.', null, null, null, '[]'::jsonb, null, 'EU', true, true, null, '[]'::jsonb, true, 'Israel', '2026-09-22', null, 'https://monday.com/lang/de', 'keins', 'monday.com Ltd.', 2012, 'Tel Aviv (Israel)', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch","und weitere"]'::jsonb, 4.3, 4.5, 3.9, 4, 4.5, 'monday.com ist eine sehr flexible Plattform für Arbeitsabläufe aller Art. Die Preise pro Sitzplatz sind fair, die Mindestgrößen und Zusatzkosten sollten Sie aber im Blick behalten.', '<h3>Das Konzept</h3><p>monday.com ist weniger ein Projekttool als ein Baukasten für Abläufe. Boards, Automatisierungen und Dashboards lassen sich für Projekte, Vertrieb, Recruiting oder Wartungspläne einsetzen.</p><h3>Preise</h3><p>Die kostenlose Version erlaubt zwei Nutzer. Basic kostet 9 €, Standard 12 € und Pro 19 € je Nutzer im Monat bei jährlicher Zahlung, zuzüglich Steuern. Die Preisrechnung auf der Anbieterseite geht von Teams mit mehreren Sitzplätzen aus, prüfen Sie deshalb die tatsächliche Staffel für Ihre Teamgröße.</p><h3>Datenschutz</h3><p>monday.com bietet eine Datenhaltung in der EU an. Richten Sie diese vor dem Start ein und schließen Sie den Auftragsverarbeitungsvertrag ab.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false)
